ALTER TABLE public.relay_entries ADD COLUMN run_splits jsonb NOT NULL DEFAULT '[]', ADD COLUMN place integer;
DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('public.guard_seeding_entry()'::regprocedure) INTO d;d:=replace(d,'BEGIN','BEGIN IF TG_TABLE_NAME=''relay_entries'' AND TG_OP=''UPDATE'' AND (to_jsonb(NEW)-ARRAY[''finals_time_ms'',''status'',''dq_code'',''points_scored'',''is_exhibition'',''run_splits'',''place'']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY[''finals_time_ms'',''status'',''dq_code'',''points_scored'',''is_exhibition'',''run_splits'',''place'']) AND NEW.status IN(''COMPLETED'',''DQ'',''NS'',''DNF'') THEN RETURN NEW; END IF;');EXECUTE d;
SELECT pg_get_functiondef('public.save_run_heat(uuid,uuid,integer,text,jsonb)'::regprocedure) INTO d;
d:=replace(d,'IF jsonb_array_length(coalesce(r->''splits'',''[]''))>0 THEN RAISE EXCEPTION ''Parciales de relevo no disponibles; no se guardará información incompleta''; END IF;', 'prev:=0;lastdist:=0; IF jsonb_typeof(coalesce(r->''splits'',''[]'')) IS DISTINCT FROM ''array'' THEN RAISE EXCEPTION ''Parciales inválidos''; END IF; FOR split IN SELECT value FROM jsonb_array_elements(coalesce(r->''splits'',''[]'')) LOOP IF split->>''timeMs'' IS NULL OR split->>''distance'' IS NULL OR split->>''timeMs''!~''^[0-9]+$'' OR split->>''distance''!~''^[0-9]+$'' THEN RAISE EXCEPTION ''Parcial no entero''; END IF;dist:=(split->>''distance'')::integer; IF dist<=lastdist OR dist>ev.distance OR (split->>''timeMs'')::integer<=prev OR (ms IS NOT NULL AND (split->>''timeMs'')::integer>ms) THEN RAISE EXCEPTION ''Parciales fuera de orden''; END IF;prev:=(split->>''timeMs'')::integer;lastdist:=dist; END LOOP; UPDATE public.relay_entries SET run_splits=coalesce(r->''splits'',''[]'') WHERE id=relay.id;');
d:=replace(d,'WITH ranked AS(SELECT x.id,rank()', 'UPDATE public.relay_entries SET points_scored=0,place=NULL WHERE event_id=p_event AND owner_id=auth.uid(); WITH placed_rows AS(SELECT id,rank() OVER(ORDER BY finals_time_ms) pos FROM public.relay_entries WHERE event_id=p_event AND status=''COMPLETED'' AND NOT is_exhibition) UPDATE public.relay_entries x SET place=p.pos FROM placed_rows p WHERE p.id=x.id; WITH ranked AS(SELECT x.id,rank()');EXECUTE d;
END $$;
CREATE FUNCTION public.configure_run_points(p_meet uuid,p_individual jsonb,p_relay jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE e record; pts jsonb; BEGIN
IF NOT public.has_role(auth.uid(),'admin') OR NOT EXISTS(SELECT 1 FROM public.meets WHERE id=p_meet AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'No autorizado'; END IF;
IF jsonb_typeof(p_individual) IS DISTINCT FROM 'array' OR jsonb_typeof(p_relay) IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_individual||p_relay) x WHERE jsonb_typeof(x)<>'number' OR x::text::numeric<0) THEN RAISE EXCEPTION 'Puntos inválidos'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(p_meet::text||':run',0));
UPDATE public.meets SET scoring_system=jsonb_build_object('individual',p_individual,'relay',p_relay) WHERE id=p_meet;
FOR e IN SELECT DISTINCT event_id,round FROM public.results WHERE meet_id=p_meet LOOP PERFORM public.recalculate_run_event(e.event_id,e.round); END LOOP;
pts:=p_relay; UPDATE public.relay_entries SET points_scored=0 WHERE meet_id=p_meet;
WITH ranked AS(SELECT x.id,rank() OVER(PARTITION BY x.event_id ORDER BY x.finals_time_ms) pos,count(*) OVER(PARTITION BY x.event_id,x.finals_time_ms) tied FROM public.relay_entries x JOIN public.clubs c ON c.id=x.club_id WHERE x.meet_id=p_meet AND x.status='COMPLETED' AND NOT x.is_exhibition AND NOT c.is_unattached), scored AS(SELECT x.id,(SELECT coalesce(sum(coalesce((pts->>k)::numeric,0)),0)/x.tied FROM generate_series(x.pos::integer-1,x.pos::integer+x.tied::integer-2) k) points FROM ranked x) UPDATE public.relay_entries x SET points_scored=s.points FROM scored s WHERE x.id=s.id;
END $$;
REVOKE ALL ON FUNCTION public.configure_run_points(uuid,jsonb,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.configure_run_points(uuid,jsonb,jsonb) TO authenticated;